def algorithm(func, dim, lb, ub, budget, rng):
    pop_size = int(np.sqrt(budget))
    max_iter = budget // pop_size
    x_best = np.zeros(dim)
    f_best = float('inf')
    for t in range(max_iter):
        X = (ub - lb) * rng.rand(pop_size, dim) + lb
        fit = func(X)
        idx = np.argsort(fit)[:int(0.2*pop_size)]
        fit[idx] = 1 / (fit[idx] ** 0.5)
        for i in range(pop_size):
            mu = X[i]
            v = X[np.random.choice(idx, size=3, replace=False), :]
            for j in range(dim):
                r1 = rng.uniform(0, 1)
                if r1 < 0.2:
                    mu[j] += (v[:,j] - mu[j]) * np.sin(np.pi * rng.rand())
                else:
                    mu[j] += v[np.random.choice(idx, size=1)[0], j] + (np.abs(v[np.random.choice(idx, size=1)[0], j] - mu[j]))*rng.uniform(-1, 1)
            X[i] = mu
        fit = func(X)
        idx = np.argsort(fit)[:int(0.2*pop_size)]
        if t < max_iter - 10:
            best_idx = idx[np.argmax(fit[idx])]
            if fit[best_idx] < f_best:
                x_best = X[best_idx]
                f_best = fit[best_idx]
        else:
            best_idx = np.argmin(fit)
            if fit[best_idx] < f_best:
                x_best = X[best_idx]
                f_best = fit[best_idx]
    return x_best

def algorithm(func, dim, lb, ub, budget, rng):
    def bounds(x):
        return np.clip(x, lb, ub)

    def fitness(x):
        x = bounds(x)
        return func(x)

    def stepsize(budget_left, population_size):
        if budget_left < 5 * dim:
            return 1e-6
        else:
            return 0.25 / (population_size ** (2/len(rng)))

    def cma_es(population_size, budget_left):
        mean = np.zeros(dim)
        sigma = stepsize(budget_left, population_size)
        lambda_ = population_size

        for _ in range(int(budget / population_size)):
            # Sample
            population = rng.randn(population_size, dim) + mean
            fitness_values = [fitness(x) for x in population]
            indices = np.argsort(fitness_values)

            # Update
            top = np.array([population[i] for i in indices[:int(lambda_/2)]])
            bottom = np.array([population[i] for i in indices[int(lambda_/2):]])

            mean_new = np.mean(top, axis=0)
            sigma_new = np.mean(np.linalg.norm(top - mean_new, axis=1)) / 0.5

            # Adapt step size
            sigma *= (budget_left // population_size) ** (2/len(rng))

            if fitness_values[indices[0]] < 10 * dim:
                return mean_new

            mean = mean_new
            sigma = sigma_new

        return mean

